import type { TalkingPortrait } from './TalkingPortrait';
import { revealTimeline, visibleCount } from './timing';
import type { MouthDriver } from './types';

export interface SpriteTalkOptions {
  /** Caractères par seconde (doit correspondre au typewriter du jeu). Défaut 28. */
  cps?: number;
  /** Respecte les pauses de ponctuation (comme `typewrite`). Défaut `true`. */
  pauses?: boolean;
  /**
   * Écart entre deux caractères (ms) au-delà duquel on repasse en idle le temps
   * de la pause. Défaut `Infinity` : la boucle `talk` tient toute la réplique
   * (repasser en idle à chaque point fait sauter la planche). À régler vers
   * 600+ pour ne marquer que les longs silences.
   */
  pauseGap?: number;
}

/**
 * Driver pour portraits en spritesheet (`TalkingPortrait.setSpriteSheet`) :
 * boucle `talk` pendant toute la révélation du texte, `idle` à la fin (et,
 * si `pauseGap` est fini, pendant les longues pauses). Pas de forme de bouche par caractère : c'est la
 * boucle dessinée qui fait le « Sam & Max ».
 */
export class SpriteTalk implements MouthDriver {
  private opts: Required<SpriteTalkOptions>;
  private times: number[] = [];
  private total = 0;
  private start = 0;
  private active = false;
  private resolve: (() => void) | null = null;
  private destroyed = false;

  constructor(
    private face: TalkingPortrait,
    opts: SpriteTalkOptions = {},
  ) {
    this.opts = { cps: 28, pauses: true, pauseGap: Infinity, ...opts };
  }

  get speaking(): boolean {
    return this.active;
  }

  get cps(): number {
    return this.opts.cps;
  }

  set cps(v: number) {
    this.opts.cps = v;
  }

  /** Boucle `talk` le temps de « dire » `text`. Résout à la fin (ou sur `idle()`). */
  speak(text: string, opts: { cps?: number } = {}): Promise<void> {
    if (this.destroyed) return Promise.resolve();
    this.finish();
    const tl = revealTimeline(text, opts.cps ?? this.opts.cps, this.opts.pauses);
    this.times = tl.times;
    this.total = tl.total;
    this.start = this.face.scene.time.now;
    this.active = true;
    this.face.claim(this);
    this.face.scene.events.on('update', this.tick);
    this.face.setTalking(true);
    return new Promise((r) => (this.resolve = r));
  }

  /** Parle sans texte (VO, durée inconnue) jusqu'à `idle()`. */
  talk(): void {
    if (this.destroyed) return;
    this.finish();
    this.face.claim(this);
    this.face.setTalking(true);
  }

  idle(): void {
    this.finish();
    this.face.setTalking(false);
  }

  destroy(): void {
    if (this.destroyed) return;
    this.idle();
    this.destroyed = true;
    this.face.release(this);
  }

  private finish(): void {
    if (this.active) this.face.scene.events.off('update', this.tick);
    this.active = false;
    const r = this.resolve;
    this.resolve = null;
    r?.();
  }

  private tick = (): void => {
    const elapsed = this.face.scene.time.now - this.start;
    if (elapsed >= this.total) {
      this.idle();
      return;
    }
    if (this.opts.pauseGap === Infinity) return;
    // écart entre le dernier caractère affiché et le suivant : long = pause de ponctuation
    const i = visibleCount(this.times, elapsed);
    const prev = this.times[i - 1] ?? 0;
    const next = this.times[i] ?? this.total;
    this.face.setTalking(next - prev <= this.opts.pauseGap);
  };
}
