import type { TalkingPortrait } from './TalkingPortrait';
import { pauseAfter, revealTimeline, visibleCount } from './timing';
import type { MouthDriver, MouthShape } from './types';

export interface TypewriterMouthOptions {
  /** Caractères par seconde (doit correspondre au typewriter du jeu). Défaut 28. */
  cps?: number;
  /** Durée minimale d'une forme (ms) : évite un battement illisible. Défaut 75. */
  minHold?: number;
  /** Respecte les pauses de ponctuation (comme `typewrite`). Défaut `true`. */
  pauses?: boolean;
  /** Mode manuel (`pulse`) : bouche refermée après ce délai sans caractère (ms). Défaut 140. */
  closeAfter?: number;
}

/** Forme de bouche suggérée pour un caractère (FR/EN, accents ignorés). */
export function shapeForChar(ch: string): MouthShape {
  const c = ch.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  if (!c || pauseAfter(ch)) return 'closed';
  if (c === 'a') return 'wide';
  if (c === 'e' || c === 'o') return 'open';
  if (c === 'i' || c === 'y' || c === 'u') return 'small';
  if (c === 'm' || c === 'b' || c === 'p') return 'closed';
  if (/[0-9]/.test(c)) return 'open';
  if (/[a-z]/.test(c)) return 'small';
  if (/\s/.test(c)) return 'small';
  return 'closed';
}

/** Variante pour ne pas figer la bouche sur des voyelles répétées. */
function alternate(shape: MouthShape): MouthShape {
  switch (shape) {
    case 'wide':
      return 'open';
    case 'open':
      return 'small';
    case 'small':
      return 'open';
    default:
      return 'closed';
  }
}

/**
 * Driver « rythme du texte » : anime la bouche au débit du typewriter, sans
 * audio. `speak(text)` tourne en autonomie ; `pulse(ch)` permet de piloter
 * caractère par caractère depuis le typewriter du jeu.
 */
export class TypewriterMouth implements MouthDriver {
  private opts: Required<TypewriterMouthOptions>;
  private times: number[] = [];
  private text = '';
  private total = 0;
  private start = 0;
  private lastChange = -Infinity;
  private lastPulse = -Infinity;
  private mode: 'off' | 'auto' | 'manual' = 'off';
  private resolve: (() => void) | null = null;
  private listening = false;
  private destroyed = false;

  constructor(
    private face: TalkingPortrait,
    opts: TypewriterMouthOptions = {},
  ) {
    this.opts = { cps: 28, minHold: 75, pauses: true, closeAfter: 140, ...opts };
  }

  get speaking(): boolean {
    return this.mode !== 'off';
  }

  /** Débit courant (chars/s). */
  get cps(): number {
    return this.opts.cps;
  }

  set cps(v: number) {
    this.opts.cps = v;
  }

  /** Anime la bouche le temps de « dire » `text`. Résout à la fin (ou sur `idle()`). */
  speak(text: string, opts: { cps?: number } = {}): Promise<void> {
    if (this.destroyed) return Promise.resolve();
    this.finish();
    const tl = revealTimeline(text, opts.cps ?? this.opts.cps, this.opts.pauses);
    this.text = text;
    this.times = tl.times;
    this.total = tl.total;
    this.start = this.now();
    this.lastChange = -Infinity;
    this.mode = 'auto';
    this.face.claim(this);
    this.listen(true);
    return new Promise((r) => (this.resolve = r));
  }

  /** Mode manuel : signale qu'un caractère vient d'apparaître. */
  pulse(ch: string): void {
    if (this.destroyed) return;
    if (this.mode !== 'manual') {
      this.finish();
      this.mode = 'manual';
      this.face.claim(this);
      this.listen(true);
    }
    const now = this.now();
    this.lastPulse = now;
    if (now - this.lastChange >= this.opts.minHold) this.apply(shapeForChar(ch), now);
  }

  idle(): void {
    if (this.mode === 'off') return;
    this.finish();
    this.face.setMouth('closed');
  }

  destroy(): void {
    if (this.destroyed) return;
    this.idle();
    this.destroyed = true;
    this.face.release(this);
  }

  // ---------------------------------------------------------------------------

  private now(): number {
    return this.face.scene.time.now;
  }

  private finish(): void {
    this.mode = 'off';
    this.listen(false);
    const r = this.resolve;
    this.resolve = null;
    r?.();
  }

  private listen(on: boolean): void {
    const events = this.face.scene.events;
    if (on && !this.listening) events.on('update', this.tick);
    if (!on && this.listening) events.off('update', this.tick);
    this.listening = on;
  }

  private apply(shape: MouthShape, now: number): void {
    const cur = this.face.mouth;
    const next = shape === cur && shape !== 'closed' ? alternate(shape) : shape;
    if (next !== cur) this.face.setMouth(next);
    this.lastChange = now;
  }

  private tick = (): void => {
    const now = this.now();
    if (this.mode === 'manual') {
      if (now - this.lastPulse > this.opts.closeAfter) this.idle();
      return;
    }
    const elapsed = now - this.start;
    if (elapsed >= this.total) {
      this.idle();
      return;
    }
    if (now - this.lastChange < this.opts.minHold) return;
    const i = Math.max(0, visibleCount(this.times, elapsed) - 1);
    this.apply(shapeForChar(this.text[i] ?? ''), now);
  };
}
