import type Phaser from 'phaser';
import { revealTimeline, visibleCount } from './timing';

export interface TypewriteOptions {
  /** Caractères par seconde. Défaut 30. */
  cps?: number;
  /** Pauses après la ponctuation. Défaut `true`. */
  pauses?: boolean;
  /** Appelé à chaque nouveau caractère visible (pour piloter `TypewriterMouth.pulse`, un son…). */
  onChar?: (ch: string, index: number) => void;
}

export interface TypewriteHandle {
  /** Résout quand tout le texte est affiché (fin normale ou `skip()`), `false` si `stop()`. */
  readonly done: Promise<boolean>;
  readonly finished: boolean;
  /** Affiche tout le texte immédiatement. */
  skip(): void;
  /** Interrompt sans compléter le texte. */
  stop(): void;
}

/**
 * Révèle progressivement `text` dans un `Phaser.GameObjects.Text`.
 * Le retour à la ligne est calculé sur le texte complet d'abord : les mots
 * ne sautent pas d'une ligne à l'autre pendant la frappe.
 */
export function typewrite(target: Phaser.GameObjects.Text, text: string, opts: TypewriteOptions = {}): TypewriteHandle {
  const scene = target.scene;
  const full = target.style.wordWrapWidth ? target.getWrappedText(text).join('\n') : text;
  const { times, total } = revealTimeline(full, opts.cps ?? 30, opts.pauses ?? true);
  const start = scene.time.now;
  let shown = 0;
  let finished = false;
  let resolve!: (v: boolean) => void;
  const done = new Promise<boolean>((r) => (resolve = r));

  const end = (complete: boolean) => {
    if (finished) return;
    finished = true;
    scene.events.off('update', tick);
    if (complete && target.active) target.setText(full);
    resolve(complete);
  };
  const tick = () => {
    if (!target.active) return end(false);
    const elapsed = scene.time.now - start;
    const n = visibleCount(times, elapsed);
    if (n !== shown) {
      for (let i = shown; i < n; i++) opts.onChar?.(full[i], i);
      shown = n;
      target.setText(full.slice(0, n));
    }
    if (elapsed >= total) end(true);
  };

  target.setText('');
  if (!full.length) end(true);
  else scene.events.on('update', tick);

  return {
    done,
    get finished() {
      return finished;
    },
    skip: () => end(true),
    stop: () => end(false),
  };
}
