import type Phaser from 'phaser';
import type { MouthShape, MouthStyle } from './types';
import { MOUTH_SHAPES } from './types';

/** Taille (px) des textures de bouche générées ; affichées ensuite à l'échelle voulue. */
export const MOUTH_TEX_W = 128;
export const MOUTH_TEX_H = 80;

const DEFAULT_STYLE: Required<MouthStyle> = {
  lipColor: '#b8505a',
  innerColor: '#2a0f18',
  teethColor: '#f4efe6',
  tongueColor: '#d96a7a',
  outlineColor: '#1a0a10',
};

export function resolveMouthStyle(style?: MouthStyle): Required<MouthStyle> {
  const out = { ...DEFAULT_STYLE };
  for (const [k, v] of Object.entries(style ?? {})) if (v !== undefined) (out as Record<string, unknown>)[k] = v;
  return out;
}

function styleId(s: Required<MouthStyle>): string {
  return [s.lipColor, s.innerColor, s.teethColor, s.tongueColor, s.outlineColor].map((c) => (c ?? 'none').replace('#', '')).join('-');
}

/** Clé de texture d'une forme pour un style donné. */
export function mouthTextureKey(shape: MouthShape, style?: MouthStyle): string {
  return `tp-mouth:${styleId(resolveMouthStyle(style))}:${shape}`;
}

/**
 * Génère (une seule fois par style) les 4 textures de bouche procédurales et
 * renvoie leurs clés. Toutes partagent le même cadre, centré : on peut
 * permuter la texture d'une Image sans la repositionner.
 */
export function ensureMouthTextures(scene: Phaser.Scene, style?: MouthStyle): Record<MouthShape, string> {
  const s = resolveMouthStyle(style);
  const keys = {} as Record<MouthShape, string>;
  for (const shape of MOUTH_SHAPES) {
    const key = mouthTextureKey(shape, s);
    keys[shape] = key;
    if (scene.textures.exists(key)) continue;
    const tex = scene.textures.createCanvas(key, MOUTH_TEX_W, MOUTH_TEX_H);
    if (!tex) continue;
    drawMouth(tex.getContext(), shape, s);
    tex.refresh();
  }
  return keys;
}

/** Dessine une forme de bouche stylisée sur un contexte 2D (MOUTH_TEX_W × MOUTH_TEX_H). */
export function drawMouth(ctx: CanvasRenderingContext2D, shape: MouthShape, style?: MouthStyle): void {
  const s = resolveMouthStyle(style);
  const cx = MOUTH_TEX_W / 2;
  const cy = MOUTH_TEX_H / 2;
  ctx.clearRect(0, 0, MOUTH_TEX_W, MOUTH_TEX_H);
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  switch (shape) {
    case 'closed':
      drawClosed(ctx, cx, cy, s);
      break;
    case 'small':
      drawOpen(ctx, cx, cy, 17, 8, 5, s, false);
      break;
    case 'open':
      drawOpen(ctx, cx, cy, 27, 17, 6, s, true);
      break;
    case 'wide':
      drawOpen(ctx, cx, cy + 2, 40, 25, 6, s, true);
      break;
  }
}

function drawClosed(ctx: CanvasRenderingContext2D, cx: number, cy: number, s: Required<MouthStyle>): void {
  const w = 34;
  const lens = () => {
    ctx.beginPath();
    ctx.moveTo(cx - w, cy);
    ctx.bezierCurveTo(cx - w * 0.5, cy - 10, cx - 6, cy - 9, cx, cy - 6);
    ctx.bezierCurveTo(cx + 6, cy - 9, cx + w * 0.5, cy - 10, cx + w, cy);
    ctx.quadraticCurveTo(cx, cy + 15, cx - w, cy);
    ctx.closePath();
  };
  if (s.outlineColor) {
    lens();
    ctx.lineWidth = 5;
    ctx.strokeStyle = s.outlineColor;
    ctx.stroke();
  }
  lens();
  ctx.fillStyle = s.lipColor;
  ctx.fill();
  // commissure : léger sourire
  ctx.beginPath();
  ctx.moveTo(cx - w + 2, cy);
  ctx.quadraticCurveTo(cx, cy + 4, cx + w - 2, cy);
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = s.outlineColor ?? s.innerColor;
  ctx.stroke();
  highlight(ctx, cx, cy + 6, w * 0.35);
}

function drawOpen(
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  rx: number,
  ry: number,
  lip: number,
  s: Required<MouthStyle>,
  details: boolean,
): void {
  const outer = () => {
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx + lip, ry + lip, 0, 0, Math.PI * 2);
  };
  if (s.outlineColor) {
    outer();
    ctx.lineWidth = 5;
    ctx.strokeStyle = s.outlineColor;
    ctx.stroke();
  }
  outer();
  ctx.fillStyle = s.lipColor;
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
  ctx.fillStyle = s.innerColor;
  ctx.fill();
  ctx.clip();
  if (details && s.tongueColor) {
    ctx.beginPath();
    ctx.ellipse(cx, cy + ry * 0.85, rx * 0.62, ry * 0.55, 0, 0, Math.PI * 2);
    ctx.fillStyle = s.tongueColor;
    ctx.fill();
  }
  if (details && s.teethColor) {
    ctx.fillStyle = s.teethColor;
    ctx.fillRect(cx - rx, cy - ry, rx * 2, ry * 0.42);
  }
  ctx.restore();

  if (s.outlineColor) {
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = s.outlineColor;
    ctx.stroke();
  }
  highlight(ctx, cx, cy + ry + lip * 0.5, rx * 0.35);
}

function highlight(ctx: CanvasRenderingContext2D, cx: number, y: number, half: number): void {
  ctx.beginPath();
  ctx.moveTo(cx - half, y);
  ctx.quadraticCurveTo(cx, y + 1.5, cx + half, y);
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'rgba(255,255,255,0.35)';
  ctx.stroke();
}
