import type { TalkingPortrait } from './TalkingPortrait';
import type { MouthDriver, MouthShape } from './types';

/** Sous-ensemble utilisé de `@beer-digital/lipsync-engine` (pas de dépendance de types). */
export interface LipSyncModule {
  LipSyncEngine: new (opts?: Record<string, unknown>) => LipSyncEngineLike;
}

interface LipSyncEngineLike {
  init(): Promise<void>;
  attachElement(el: HTMLMediaElement): void;
  startAnalysis(): void;
  stopAnalysis?(): void;
  destroy?(): void;
  on(ev: 'viseme', cb: (frame: VisemeFrame) => void): void;
}

interface VisemeFrame {
  viseme?: string;
  intensity?: number;
  shape?: { open?: number; width?: number; round?: number };
}

export interface AudioMouthOptions {
  /**
   * Moteur de visèmes :
   * - module importé (`await import('@beer-digital/lipsync-engine')`) : recommandé avec un bundler ;
   * - `'auto'` (défaut) : tente un import dynamique, sinon analyseur intégré ;
   * - `null` : analyseur intégré (AnalyserNode, zéro dépendance).
   */
  lipsync?: LipSyncModule | 'auto' | null;
  /** Options passées à `new LipSyncEngine(...)`. */
  lipsyncOptions?: Record<string, unknown>;
  /** AudioContext partagé (sinon créé à la demande). */
  context?: AudioContext;
  /** Gain de détection de l'analyseur intégré. Défaut 1. */
  sensitivity?: number;
  /** Durée minimale d'une forme (ms). Défaut 70. */
  minHold?: number;
  volume?: number;
}

const LIPSYNC_PKG = '@beer-digital/lipsync-engine';

async function loadLipsync(opt: AudioMouthOptions['lipsync']): Promise<LipSyncModule | null> {
  if (opt === null) return null;
  if (opt && opt !== 'auto') return opt;
  try {
    // spécificateur variable : le bundler ne tente pas de le résoudre (peer optionnelle)
    const mod = (await import(/* @vite-ignore */ LIPSYNC_PKG)) as Partial<LipSyncModule>;
    return mod.LipSyncEngine ? (mod as LipSyncModule) : null;
  } catch {
    return null;
  }
}

/** Forme de bouche depuis une frame `lipsync-engine` (open/width/round 0..1). */
export function shapeFromViseme(frame: VisemeFrame): MouthShape {
  const open = frame.shape?.open ?? (frame.viseme === 'sil' ? 0 : (frame.intensity ?? 0) * 0.6);
  const width = frame.shape?.width ?? 0.5;
  const round = frame.shape?.round ?? 0;
  if (open < 0.08) return 'closed';
  if (open < 0.3 || round > 0.7) return 'small';
  if (open > 0.7 && width >= 0.55) return 'wide';
  return 'open';
}

/**
 * Driver audio (VO). Analyse le son joué et anime la bouche. Dégrade
 * proprement : lipsync-engine → analyseur WebAudio intégré → battement
 * simple pendant la lecture si WebAudio est indisponible.
 */
export class AudioMouth implements MouthDriver {
  private ctx: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private engine: LipSyncEngineLike | null = null;
  private bufferSource: AudioBufferSourceNode | null = null;
  private timeData: Float32Array<ArrayBuffer> | null = null;
  private freqData: Uint8Array<ArrayBuffer> | null = null;
  private level = 0;
  private lastChange = -Infinity;
  private playing = false;
  private resolve: (() => void) | null = null;
  private listening = false;
  private destroyed = false;
  private readonly sensitivity: number;
  private readonly minHold: number;

  private constructor(
    private face: TalkingPortrait,
    private element: HTMLMediaElement | null,
    private buffer: AudioBuffer | null,
    private opts: AudioMouthOptions,
  ) {
    this.sensitivity = opts.sensitivity ?? 1;
    this.minHold = opts.minHold ?? 70;
  }

  /** Charge une VO depuis une URL (lecture en streaming via `<audio>`). */
  static async fromUrl(face: TalkingPortrait, url: string, opts: AudioMouthOptions = {}): Promise<AudioMouth> {
    const el = new Audio();
    el.crossOrigin = 'anonymous';
    el.preload = 'auto';
    el.src = url;
    return AudioMouth.fromElement(face, el, opts);
  }

  /** Utilise un élément `<audio>`/`<video>` existant. */
  static async fromElement(face: TalkingPortrait, el: HTMLMediaElement, opts: AudioMouthOptions = {}): Promise<AudioMouth> {
    const m = new AudioMouth(face, el, null, opts);
    if (opts.volume !== undefined) el.volume = opts.volume;
    const lib = await loadLipsync(opts.lipsync);
    if (lib) {
      try {
        const engine = new lib.LipSyncEngine({ ...opts.lipsyncOptions });
        await engine.init();
        engine.attachElement(el);
        engine.on('viseme', (f) => m.push(shapeFromViseme(f)));
        m.engine = engine;
        return m;
      } catch (e) {
        console.warn('[talking-portrait] lipsync-engine indisponible, analyseur intégré utilisé', e);
      }
    }
    m.setupAnalyser((ctx) => ctx.createMediaElementSource(el));
    return m;
  }

  /** Utilise un AudioBuffer déjà décodé (VO synthétisée, pack audio…). */
  static fromBuffer(face: TalkingPortrait, buffer: AudioBuffer, opts: AudioMouthOptions = {}): AudioMouth {
    const m = new AudioMouth(face, null, buffer, opts);
    m.setupAnalyser(null);
    return m;
  }

  get speaking(): boolean {
    return this.playing;
  }

  /** Lance la lecture et anime la bouche ; résout à la fin du son (ou sur `idle()`). */
  async speak(): Promise<void> {
    if (this.destroyed) return;
    this.stopPlayback();
    this.face.claim(this);
    this.playing = true;
    this.level = 0;
    this.lastChange = -Infinity;
    const finished = new Promise<void>((r) => (this.resolve = r));
    try {
      if (this.ctx?.state === 'suspended') await this.ctx.resume();
      if (this.element) {
        this.element.currentTime = 0;
        this.element.onended = () => this.idle();
        this.engine?.startAnalysis();
        await this.element.play();
      } else if (this.buffer && this.ctx && this.analyser) {
        const src = this.ctx.createBufferSource();
        src.buffer = this.buffer;
        let out: AudioNode = this.analyser;
        if (this.opts.volume !== undefined) {
          const gain = this.ctx.createGain();
          gain.gain.value = this.opts.volume;
          gain.connect(this.analyser);
          out = gain;
        }
        src.connect(out);
        src.onended = () => {
          if (this.bufferSource === src) this.idle();
        };
        this.bufferSource = src;
        src.start();
      } else {
        this.idle();
      }
    } catch (e) {
      console.warn('[talking-portrait] lecture audio impossible', e);
      this.idle();
    }
    if (this.playing && !this.engine) this.listen(true);
    return finished;
  }

  idle(): void {
    if (this.playing) this.stopPlayback();
    this.playing = false;
    this.listen(false);
    if (!this.destroyed) this.face.setMouth('closed');
    const r = this.resolve;
    this.resolve = null;
    r?.();
  }

  destroy(): void {
    if (this.destroyed) return;
    this.idle();
    this.destroyed = true;
    this.engine?.stopAnalysis?.();
    this.engine?.destroy?.();
    this.engine = null;
    if (this.element) this.element.onended = null;
    if (!this.opts.context) void this.ctx?.close().catch(() => undefined);
    this.face.release(this);
  }

  // ---------------------------------------------------------------------------

  private setupAnalyser(source: ((ctx: AudioContext) => AudioNode) | null): void {
    try {
      const Ctx = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!this.opts.context && !Ctx) return;
      const ctx = this.opts.context ?? new Ctx();
      const analyser = ctx.createAnalyser();
      analyser.fftSize = 1024;
      analyser.smoothingTimeConstant = 0.3;
      analyser.connect(ctx.destination);
      source?.(ctx).connect(analyser);
      this.ctx = ctx;
      this.analyser = analyser;
      this.timeData = new Float32Array(analyser.fftSize);
      this.freqData = new Uint8Array(analyser.frequencyBinCount);
    } catch (e) {
      // ex. élément déjà relié à un autre contexte : lecture seule + battement simple
      console.warn('[talking-portrait] WebAudio indisponible, battement simple', e);
      this.ctx = null;
      this.analyser = null;
    }
  }

  private stopPlayback(): void {
    if (this.element) {
      this.element.pause();
      this.engine?.stopAnalysis?.();
    }
    if (this.bufferSource) {
      const src = this.bufferSource;
      this.bufferSource = null;
      try {
        src.stop();
      } catch {
        /* déjà arrêté */
      }
    }
  }

  private listen(on: boolean): void {
    const events = this.face.scene.events;
    if (on && !this.listening) events.on('update', this.tick);
    if (!on && this.listening) events.off('update', this.tick);
    this.listening = on;
  }

  /** Applique une forme en respectant `minHold`. */
  private push(shape: MouthShape): void {
    if (!this.playing || this.destroyed) return;
    const now = this.face.scene.time.now;
    if (now - this.lastChange < this.minHold || shape === this.face.mouth) return;
    this.face.setMouth(shape);
    this.lastChange = now;
  }

  private tick = (): void => {
    if (!this.analyser || !this.timeData || !this.freqData || !this.ctx) {
      // pas d'analyse possible : battement régulier tant que ça joue
      const t = this.face.scene.time.now;
      this.push(Math.floor(t / 110) % 3 === 0 ? 'small' : Math.floor(t / 110) % 3 === 1 ? 'open' : 'closed');
      return;
    }
    this.analyser.getFloatTimeDomainData(this.timeData);
    let sum = 0;
    for (let i = 0; i < this.timeData.length; i++) sum += this.timeData[i] * this.timeData[i];
    const rms = Math.sqrt(sum / this.timeData.length) * this.sensitivity;
    // enveloppe : attaque rapide, relâche plus lente
    this.level += (rms - this.level) * (rms > this.level ? 0.6 : 0.25);

    this.analyser.getByteFrequencyData(this.freqData);
    const hz = this.ctx.sampleRate / this.analyser.fftSize;
    let low = 0;
    let high = 0;
    for (let i = 1; i < this.freqData.length; i++) {
      const f = i * hz;
      if (f < 1000) low += this.freqData[i];
      else if (f > 2500 && f < 7000) high += this.freqData[i];
    }
    const sibilant = high > low * 0.9;
    const v = Math.min(1, this.level * 6);
    let shape: MouthShape;
    if (v < 0.08) shape = 'closed';
    else if (v < 0.25 || sibilant) shape = 'small';
    else if (v < 0.55) shape = 'open';
    else shape = 'wide';
    this.push(shape);
  };
}
