/** Pauses (en « caractères » de durée) après la ponctuation. */
const PAUSES: Record<string, number> = {
  ',': 2.5,
  ';': 3,
  ':': 3,
  '.': 6,
  '!': 6,
  '?': 6,
  '…': 8,
};

/** Pause supplémentaire (en caractères) après `ch`, partagée par le typewriter et la bouche. */
export function pauseAfter(ch: string): number {
  return PAUSES[ch] ?? 0;
}

/**
 * Instants (ms) d'apparition de chaque caractère pour un débit donné.
 * `times[i]` = moment où le caractère i devient visible ; `total` = fin de la ligne.
 */
export function revealTimeline(text: string, cps: number, pauses = true): { times: number[]; total: number } {
  const step = 1000 / Math.max(1, cps);
  const times: number[] = [];
  let t = 0;
  for (let i = 0; i < text.length; i++) {
    times.push(t);
    t += step;
    if (pauses) {
      const ch = text[i];
      // « ... » ou « ?! » : une seule pause en fin de groupe
      const next = text[i + 1];
      if (!(next && pauseAfter(next) && pauseAfter(ch))) t += pauseAfter(ch) * step;
    }
  }
  return { times, total: t };
}

/** Nombre de caractères visibles à l'instant `elapsed`. */
export function visibleCount(times: number[], elapsed: number): number {
  let lo = 0;
  let hi = times.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (times[mid] <= elapsed) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}
