import type Phaser from 'phaser';
import { ensureMouthTextures, MOUTH_TEX_W } from './mouths';
import type { BlinkOptions, EyeOptions, MouthDriver, MouthOptions, MouthShape, SpriteLoop, SpriteSheetOptions, TalkingPortraitOptions } from './types';

const DEFAULT_MOUTH = { x: 0.5, y: 0.66, width: 0.22, rotation: 0 };

function hexToInt(c: string): number {
  return parseInt(c.replace('#', '').slice(0, 6), 16);
}

/**
 * Portrait parlant : image de base + bouche en overlay + clignement d'yeux,
 * ou spritesheet animée (boucles `idle` / `talk`, voir `setSpriteSheet`).
 *
 * Tous les ancrages (bouche, yeux) sont exprimés en fractions de la texture de
 * base (0..1), indépendamment du recadrage : changer la taille du cadre ne
 * déplace pas la bouche sur le visage.
 *
 * Aucun import Phaser à l'exécution : tout passe par la scène fournie, ce qui
 * évite les doublons de Phaser quand le package est lié (`file:`, monorepo).
 */
export class TalkingPortrait {
  readonly scene: Phaser.Scene;
  /** Conteneur racine, centré sur (x, y). */
  readonly container: Phaser.GameObjects.Container;

  private content: Phaser.GameObjects.Container;
  private base: Phaser.GameObjects.Sprite;
  private eyesClosedImg: Phaser.GameObjects.Image;
  private lids: Phaser.GameObjects.Graphics;
  private mouthImg: Phaser.GameObjects.Image;

  private width: number;
  private height: number;
  private fit: 'cover' | 'contain';
  private mouthOpts: MouthOptions = {};
  private mouthKeys: Record<MouthShape, string> | null = null;
  private blinkOpts: BlinkOptions = {};
  private eyesClosedKey: string | undefined;
  private shape: MouthShape = 'closed';
  /** Mode spritesheet : clés des animations locales du sprite de base. */
  private sheet: { key: string; idle: string; talk: string; closeHold: number } | null = null;
  private talkingNow = false;
  private closeTimer: Phaser.Time.TimerEvent | null = null;
  /** Échelle et taille (px) de la texture de base affichée. */
  private baseScale = 1;
  private baseW = 0;
  private baseH = 0;

  private blinkTimer: Phaser.Time.TimerEvent | null = null;
  private breatheTween: Phaser.Tweens.Tween | null = null;
  private driver: MouthDriver | null = null;
  private destroyed = false;

  constructor(scene: Phaser.Scene, opts: TalkingPortraitOptions) {
    this.scene = scene;
    this.width = opts.width;
    this.height = opts.height;
    this.fit = opts.fit ?? 'cover';

    this.container = scene.make.container({ x: opts.x, y: opts.y }, false);
    if (opts.depth !== undefined) this.container.setDepth(opts.depth);
    // ancré en bas pour que la respiration « soulève » le buste
    this.content = scene.make.container({ x: 0, y: this.height / 2 }, false);
    this.base = scene.make.sprite({ x: 0, y: -this.height / 2, key: '__DEFAULT' }, false).setVisible(false);
    this.eyesClosedImg = scene.make.image({ x: 0, y: -this.height / 2, key: '__DEFAULT' }, false).setVisible(false);
    this.lids = scene.make.graphics({}, false).setVisible(false);
    this.mouthImg = scene.make.image({ x: 0, y: 0, key: '__DEFAULT' }, false).setVisible(false);
    this.content.add([this.base, this.eyesClosedImg, this.lids, this.mouthImg]);
    this.container.add(this.content);
    this.container.once('destroy', () => this.cleanup());
    scene.events.once('shutdown', this.onShutdown);

    this.eyesClosedKey = opts.layers?.eyesClosed;
    this.configure({ mouth: opts.mouth, blink: opts.blink });
    if (opts.textureKey) this.setTexture(opts.textureKey, opts.frame);
    else this.layout();
    this.setBreathing(opts.breathe ?? 0.008);
  }

  /** Ajoute le portrait à un conteneur parent, ou à la scène par défaut. */
  attach(parent?: Phaser.GameObjects.Container): this {
    if (parent) parent.add(this.container);
    else this.scene.add.existing(this.container);
    return this;
  }

  /** Retire le portrait de son parent sans le détruire. */
  detach(): this {
    const parent = this.container.parentContainer;
    if (parent) parent.remove(this.container);
    else this.container.removeFromDisplayList();
    return this;
  }

  setPosition(x: number, y: number): this {
    this.container.setPosition(x, y);
    return this;
  }

  setVisible(v: boolean): this {
    this.container.setVisible(v);
    if (!v) {
      this.driver?.idle();
      this.setTalking(false);
    }
    return this;
  }

  get visible(): boolean {
    return this.container.visible;
  }

  setSize(width: number, height: number): this {
    this.width = width;
    this.height = height;
    this.content.setY(height / 2);
    this.base.setY(-height / 2);
    this.eyesClosedImg.setY(-height / 2);
    this.layout();
    return this;
  }

  /** Change le portrait de base (et éventuellement ses ancrages). */
  setTexture(key: string, frame?: string | number, opts?: { mouth?: MouthOptions; blink?: BlinkOptions; eyesClosed?: string }): this {
    this.leaveSheet();
    if (opts) {
      if ('eyesClosed' in opts) this.eyesClosedKey = opts.eyesClosed;
      this.configure(opts);
    }
    this.base.setTexture(key, frame).setVisible(true);
    this.layout();
    return this;
  }

  /**
   * Passe en mode spritesheet : le portrait joue `idle` en boucle et `talk`
   * pendant la parole. La bouche overlay et les paupières procédurales sont
   * coupées (le clignement fait partie de la boucle idle).
   *
   * ```ts
   * face.setSpriteSheet({
   *   key: 'portrait:gary', frameWidth: 256, frameHeight: 256,
   *   idle: { frames: [{ frame: 0, duration: 1800 }, { frame: 1, duration: 90 }] },
   *   talk: { frames: [2, 3, 4, 5], frameRate: 8 },
   * });
   * ```
   */
  setSpriteSheet(opts: SpriteSheetOptions): this {
    if (this.destroyed) return this;
    this.leaveSheet();
    const tex = this.scene.textures.get(opts.key);
    if (opts.frameWidth && opts.frameHeight) sliceGrid(tex, opts.frameWidth, opts.frameHeight);
    const anims = this.base.anims;
    const idle = `${opts.key}#idle`;
    const talk = `${opts.key}#talk`;
    // animations locales au sprite : reconfigurer une même clé reste possible
    for (const [k, loop] of [[idle, opts.idle], [talk, opts.talk]] as [string, SpriteLoop][]) {
      if (anims.exists(k)) anims.remove(k);
      // Phaser ≥ 3.60 : la `duration` d'une frame remplace 1000 / frameRate pour cette frame
      anims.create({ key: k, frames: loop.frames.map((f) => (typeof f === 'object' ? { key: opts.key, ...f } : { key: opts.key, frame: f })), frameRate: loop.frameRate ?? 8, repeat: -1 });
    }
    this.sheet = { key: opts.key, idle, talk, closeHold: opts.closeHold ?? 160 };
    this.talkingNow = false;
    this.shape = 'closed';
    const first = opts.idle.frames[0];
    this.base.setTexture(opts.key, typeof first === 'object' ? first.frame : first).setVisible(true);
    this.mouthImg.setVisible(false);
    this.showLids(false);
    this.layout();
    this.scheduleBlink();
    this.base.play(idle);
    return this;
  }

  /** `true` si le portrait est en mode spritesheet. */
  get hasSpriteSheet(): boolean {
    return !!this.sheet;
  }

  /** `true` pendant la boucle `talk` (mode spritesheet). */
  get talking(): boolean {
    return this.talkingNow;
  }

  /** Mode spritesheet : bascule entre les boucles `talk` et `idle`. */
  setTalking(on: boolean): this {
    this.closeTimer?.remove();
    this.closeTimer = null;
    if (!this.sheet || this.destroyed || on === this.talkingNow) return this;
    this.talkingNow = on;
    // ignoreIfPlaying : jamais de redémarrage de boucle si elle tourne déjà
    this.base.play(on ? this.sheet.talk : this.sheet.idle, true);
    return this;
  }

  /** Met à jour ancrages / style de bouche et options de clignement. */
  configure(opts: { mouth?: MouthOptions; blink?: BlinkOptions }): this {
    if (opts.mouth) {
      this.mouthOpts = { ...opts.mouth };
      this.mouthKeys = opts.mouth.sheet ? null : ensureMouthTextures(this.scene, opts.mouth.style);
    } else if (!this.mouthKeys && !this.mouthOpts.sheet) {
      this.mouthKeys = ensureMouthTextures(this.scene);
    }
    if (opts.blink) this.blinkOpts = { ...opts.blink };
    this.layout();
    this.scheduleBlink();
    return this;
  }

  /** Forme de bouche courante. */
  get mouth(): MouthShape {
    return this.shape;
  }

  setMouth(shape: MouthShape): this {
    this.shape = shape;
    if (this.destroyed) return this;
    if (this.sheet) {
      // spritesheet : toute forme ouverte = boucle talk ; fermeture différée
      if (shape !== 'closed') this.setTalking(true);
      else if (this.talkingNow && !this.closeTimer) {
        this.closeTimer = this.scene.time.delayedCall(this.sheet.closeHold, () => {
          this.closeTimer = null;
          this.setTalking(false);
        });
      }
      return this;
    }
    const sheet = this.mouthOpts.sheet;
    if (sheet) this.mouthImg.setTexture(sheet.key, sheet.frames[shape]);
    else if (this.mouthKeys) this.mouthImg.setTexture(this.mouthKeys[shape]);
    this.mouthImg.setVisible(shape !== 'closed' || this.mouthOpts.showClosed !== false);
    this.scaleMouth();
    return this;
  }

  /**
   * Déclare le driver actif (texte, audio…). Le précédent est mis au repos :
   * un seul driver anime la bouche à la fois.
   */
  claim(driver: MouthDriver): void {
    if (this.driver && this.driver !== driver) this.driver.idle();
    this.driver = driver;
  }

  release(driver: MouthDriver): void {
    if (this.driver === driver) this.driver = null;
  }

  /** Ferme la bouche et arrête le driver actif. */
  idle(): this {
    this.driver?.idle();
    this.setMouth('closed');
    this.setTalking(false);
    return this;
  }

  /** Force un clignement immédiat. */
  blink(): void {
    if (this.destroyed || !this.canBlink()) return;
    const duration = this.blinkOpts.duration ?? 130;
    this.showLids(true);
    this.scene.time.delayedCall(duration, () => this.showLids(false));
  }

  setBreathing(amplitude: number | false): this {
    this.breatheTween?.remove();
    this.breatheTween = null;
    this.content.setScale(1);
    if (amplitude && amplitude > 0) {
      this.breatheTween = this.scene.tweens.add({
        targets: this.content,
        scaleY: 1 + amplitude,
        scaleX: 1 + amplitude * 0.3,
        duration: 1900,
        yoyo: true,
        repeat: -1,
        ease: 'Sine.easeInOut',
      });
    }
    return this;
  }

  destroy(): void {
    if (this.destroyed) return;
    this.container.destroy();
    this.cleanup();
  }

  // ---------------------------------------------------------------------------

  private onShutdown = (): void => this.destroy();

  private cleanup(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.scene.events.off('shutdown', this.onShutdown);
    const driver = this.driver;
    this.driver = null;
    driver?.destroy();
    this.blinkTimer?.remove();
    this.blinkTimer = null;
    this.breatheTween?.remove();
    this.breatheTween = null;
    this.closeTimer?.remove();
    this.closeTimer = null;
  }

  private leaveSheet(): void {
    if (!this.sheet) return;
    this.closeTimer?.remove();
    this.closeTimer = null;
    this.base.stop();
    this.sheet = null;
    this.talkingNow = false;
  }

  /** Convertit un point normalisé de la texture de base en coordonnées de `content`. */
  private toLocal(nx: number, ny: number): { x: number; y: number } {
    return { x: (nx - 0.5) * this.baseW * this.baseScale, y: -this.height / 2 + (ny - 0.5) * this.baseH * this.baseScale };
  }

  private layout(): void {
    const hasBase = this.base.visible && this.base.frame && this.base.texture.key !== '__DEFAULT';
    const fw = hasBase ? this.base.frame.realWidth : this.width;
    const fh = hasBase ? this.base.frame.realHeight : this.height;
    this.baseW = fw;
    this.baseH = fh;
    const sx = this.width / fw;
    const sy = this.height / fh;
    this.baseScale = this.fit === 'cover' ? Math.max(sx, sy) : Math.min(sx, sy);
    if (hasBase) {
      this.applyFit(this.base);
      if (this.eyesClosedKey && this.scene.textures.exists(this.eyesClosedKey)) {
        this.eyesClosedImg.setTexture(this.eyesClosedKey);
        this.applyFit(this.eyesClosedImg);
      }
    }
    const m = { ...DEFAULT_MOUTH, ...this.mouthOpts };
    const p = this.toLocal(m.x, m.y);
    this.mouthImg.setPosition(p.x, p.y).setRotation(m.rotation);
    if (!this.sheet) this.setMouth(this.shape);
    if (this.lids.visible) this.drawLids();
  }

  private applyFit(img: Phaser.GameObjects.Image): void {
    const fw = img.frame.realWidth;
    const fh = img.frame.realHeight;
    const scale = this.fit === 'cover' ? Math.max(this.width / fw, this.height / fh) : Math.min(this.width / fw, this.height / fh);
    img.setScale(scale);
    // rognage centré (pas de masque : fonctionne dans n'importe quel conteneur)
    const cw = Math.min(fw, this.width / scale);
    const ch = Math.min(fh, this.height / scale);
    img.setCrop((fw - cw) / 2, (fh - ch) / 2, cw, ch);
  }

  private scaleMouth(): void {
    const m = { ...DEFAULT_MOUTH, ...this.mouthOpts };
    const target = m.width * this.baseW * this.baseScale;
    const texW = this.mouthOpts.sheet ? this.mouthImg.frame.realWidth : MOUTH_TEX_W;
    this.mouthImg.setScale(target / texW);
  }

  private canBlink(): boolean {
    if (this.sheet || this.blinkOpts.enabled === false) return false;
    const hasLayer = !!this.eyesClosedKey && this.scene.textures.exists(this.eyesClosedKey);
    return hasLayer || (this.blinkOpts.eyes?.length ?? 0) > 0;
  }

  private scheduleBlink(): void {
    this.blinkTimer?.remove();
    this.blinkTimer = null;
    if (this.destroyed || !this.canBlink()) return;
    const min = this.blinkOpts.minInterval ?? 2200;
    const max = Math.max(min, this.blinkOpts.maxInterval ?? 5200);
    this.blinkTimer = this.scene.time.delayedCall(min + Math.random() * (max - min), () => {
      this.blink();
      if (Math.random() < (this.blinkOpts.doubleChance ?? 0.15)) {
        this.scene.time.delayedCall((this.blinkOpts.duration ?? 130) * 2.2, () => this.blink());
      }
      this.scheduleBlink();
    });
  }

  private showLids(on: boolean): void {
    if (this.destroyed) return;
    const layer = !!this.eyesClosedKey && this.scene.textures.exists(this.eyesClosedKey);
    if (layer) {
      this.eyesClosedImg.setVisible(on && this.base.visible);
      this.lids.setVisible(false);
      return;
    }
    this.lids.setVisible(on);
    if (on) this.drawLids();
  }

  private drawLids(): void {
    const g = this.lids;
    g.clear();
    const lid = hexToInt(this.blinkOpts.lidColor ?? '#c98d6b');
    const lash = hexToInt(this.blinkOpts.lashColor ?? '#1a0a10');
    const unit = this.baseW * this.baseScale;
    for (const eye of this.blinkOpts.eyes ?? []) this.drawLid(g, eye, unit, lid, lash);
  }

  private drawLid(g: Phaser.GameObjects.Graphics, eye: EyeOptions, unit: number, lid: number, lash: number): void {
    const w = (eye.width ?? 0.1) * unit;
    const h = (eye.height ?? (eye.width ?? 0.1) * 0.6) * unit;
    const c = this.toLocal(eye.x, eye.y);
    g.fillStyle(lid, 1);
    g.fillEllipse(c.x, c.y, w * 1.15, h * 1.2);
    // trait de cils légèrement courbé vers le bas
    const pts: { x: number; y: number }[] = [];
    for (let i = 0; i <= 10; i++) {
      const t = i / 10;
      pts.push({ x: c.x - w / 2 + w * t, y: c.y + h * 0.12 + Math.sin(t * Math.PI) * h * 0.22 });
    }
    g.lineStyle(Math.max(1.5, w * 0.08), lash, 1);
    g.strokePoints(pts, false, false);
  }
}

/** Découpe une texture en grille de frames numérotées 0..n-1 (si absentes). */
function sliceGrid(tex: Phaser.Textures.Texture, fw: number, fh: number): void {
  const src = tex.source[0];
  if (!src) return;
  const cols = Math.floor(src.width / fw);
  const rows = Math.floor(src.height / fh);
  for (let i = 0; i < cols * rows; i++) {
    const f = tex.has(String(i)) ? tex.get(i) : null;
    if (f && f.width === fw && f.height === fh) continue;
    if (f) tex.remove(String(i));
    tex.add(i, 0, (i % cols) * fw, Math.floor(i / cols) * fh, fw, fh);
  }
}
